const storedLogArchiveWindows = `-- name: StoredLogArchiveWindows :many
SELECT period_from, period_to, mode FROM log_archives
WHERE dataset = $1 AND state IN ('stored', 'running')
`

type StoredLogArchiveWindowsRow struct {
	PeriodFrom time.Time `json:"period_from"`
	PeriodTo   time.Time `json:"period_to"`
	Mode       string    `json:"mode"`
}

// Periods already kept in a file, so a copy policy doesn't export them twice.
func (q *Queries) StoredLogArchiveWindows(ctx context.Context, dataset string) ([]StoredLogArchiveWindowsRow, error) {
	rows, err := q.db.Query(ctx, storedLogArchiveWindows, dataset)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []StoredLogArchiveWindowsRow{}
	for rows.Next() {
		var i StoredLogArchiveWindowsRow
		if err := rows.Scan(&i.PeriodFrom, &i.PeriodTo, &i.Mode); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
